    source_type: external_exports.enum(["kanban", "chat", "orchestrator", "other"]).optional().describe("Where the instruction originated (default: 'other')"),
    from_user_id: external_exports.string().optional().describe("Deprecated/ignored. The server records the authenticated Firebase uid."),
